// Types for the lines of a bulk query's results.
//
// A bulk query's JSONL doesn't have the shape of the query's result. Every
// node of every connection becomes its own line, without its nested
// connections. A node inside another node's connection gets a `__parentId`
// with that node's id. BulkLine<T> turns a query's result type, such as one
// generated by Shopify's codegen, into the union of those lines.

/** A connection, in either of Shopify's shapes */
type Connection =
  | { edges: ReadonlyArray<{ node: unknown }> }
  | { nodes: ReadonlyArray<unknown> };

type IsConnection<T> = [NonNullable<T>] extends [never]
  ? false
  : NonNullable<T> extends Connection
    ? true
    : false;

type NodeOf<C> = C extends { edges: ReadonlyArray<{ node: infer N }> }
  ? N
  : C extends { nodes: ReadonlyArray<infer N> }
    ? N
    : never;

/** Flattens intersections so hovers show plain objects */
type Simplify<T> = { [K in keyof T]: T[K] } & {};

/** An object without its connection fields, at any depth */
type WithoutConnections<T> =
  T extends ReadonlyArray<unknown>
    ? T
    : T extends object
      ? Simplify<{
          [K in keyof T as IsConnection<T[K]> extends true
            ? never
            : K]: WithoutConnections<T[K]>;
        }>
      : T;

/** The lines from every connection inside T */
type LinesIn<T, HasParent extends boolean> =
  T extends ReadonlyArray<unknown>
    ? never
    : T extends object
      ? {
          [K in keyof T]-?: IsConnection<T[K]> extends true
            ? NodeLines<NodeOf<NonNullable<T[K]>>, HasParent>
            : LinesIn<NonNullable<T[K]>, HasParent>;
        }[keyof T]
      : never;

/** A connection node's own line, plus the lines nested inside it */
type NodeLines<N, HasParent extends boolean> =
  | (HasParent extends true
      ? Simplify<WithoutConnections<N> & { __parentId: string }>
      : Simplify<WithoutConnections<N> & { __parentId?: undefined }>)
  | LinesIn<N, true>;

/**
 * The lines of a bulk query's results, from the query's result type.
 *
 * Top-level lines have no `__parentId`; nested ones have their parent's id.
 * When a node has several nested connections, select `__typename` to tell
 * their lines apart.
 *
 * @example
 * type ProductsQuery = {
 *   products: {
 *     edges: { node: { id: string; variants: { edges: { node: { id: string } }[] } } }[];
 *   };
 * };
 * type Line = BulkLine<ProductsQuery>;
 * // { id: string; __parentId?: undefined } | { id: string; __parentId: string }
 */
export type BulkLine<T> = LinesIn<T, false>;
